/**
 * @param list<Token> $tokensToInsert
 */
private static function isAttributeAlreadyPresent(Tokens $tokens, int $index, array $tokensToInsert): bool
{
    $attributeIndex = $tokens->getNextMeaningfulToken($index);
    if (!$tokens[$attributeIndex]->isGivenKind(T_ATTRIBUTE)) {
        return false;
    }

    $insertedClassName = '';
    $insertedArguments = '';
    $insertedArgumentsStarted = false;
    foreach (\array_slice($tokensToInsert, 2) as $token) {
        if ($token->isGivenKind(CT::T_ATTRIBUTE_CLOSE)) {
            break;
        }
        if ($token->equals('(')) {
            $insertedArgumentsStarted = true;
            continue;
        }
        if ($token->isWhitespace() || $token->isComment()) {
            continue;
        }
        if ($insertedArgumentsStarted) {
            $insertedArguments .= $token->getContent();
        } else {
            $insertedClassName .= $token->getContent();
        }
    }

    foreach (AttributeAnalyzer::collect($tokens, $attributeIndex) as $attributeAnalysis) {
        foreach ($attributeAnalysis->getAttributes() as $attribute) {
            $className = ltrim(self::determineAttributeFullyQualifiedName(
                $tokens,
                $attribute['name'],
                $attribute['start'],
            ), '\\');

            if (ltrim($insertedClassName, '\\') !== $className) {
                continue;
            }

            if ($insertedArguments === self::getAttributeArguments($tokens, $attribute)) {
                return true;
            }
        }
    }

    return false;
