private static function isAttributeAlreadyPresent(Tokens $tokens, int $index, array $tokensToInsert, array $insertedAttributeSignatures): bool
{
    $attributeIndex = $tokens->getNextMeaningfulToken($index);
    if (!$tokens[$attributeIndex]->isGivenKind(T_ATTRIBUTE)) {
        return false;
    }

    $insertedSignatures = self::getInsertedAttributeSignatures($tokensToInsert);
    if ([] === $insertedSignatures) {
        return false;
    }
    [$insertedClassName, $insertedArguments] = explode('|', $insertedSignatures[0], 2);

    foreach (AttributeAnalyzer::collect($tokens, $attributeIndex) as $attributeAnalysis) {
        foreach ($attributeAnalysis->getAttributes() as $attribute) {
            $className = ltrim(self::determineAttributeFullyQualifiedName(
                $tokens,
                $attribute['name'],
                $attribute['start'],
            ), '\\');

            if ($insertedClassName !== $className) {
                continue;
            }

            $arguments = self::getAttributeArguments($tokens, $attribute);

            if ($insertedArguments === $arguments) {
                return true;
            }

            if (!\in_array($className.'|'.$arguments, $insertedAttributeSignatures, true)) {
                return true;
            }
        }
    }

